import{PGlite}from'@electric-sql/pglite';import{drizzle}from'drizzle-orm/pglite';import{randomBytes}from'node:crypto';import{readFileSync}from'node:fs';import{microbiomeSamples}from'../../shared/schema';import{PrecisionStorage}from'../../server/precision-storage';import{reportDerivedTablesSql}from'./report-derived-tables';
export const nativeReport=(kind:'active-gut-microbes'|'health-scores-foods')=>({schemaVersion:'bloom-viome-findings-v1',provider:'Viome',documentKind:kind,specimenType:'not-supplied',method:'not-supplied',biologicalDates:{},reviewConfirmed:true,organisms:kind==='active-gut-microbes'?[{name:'Syntheticus alpha',reportedGroup:'Bacteria',reportedStatus:'reported_present',position:{page:1,column:1,row:1}}]:[],assessments:[],foods:kind==='health-scores-foods'?[{name:'Synthetic food',reportedCategory:'Enjoy',position:{page:1,column:1,row:1}}]:[]});
export const geneticReport=(genotype='AG')=>({provider:'manual',consent:true,source:'Synthetic dataset',strand:'forward',collectedAt:'2026-10-01T12:00:00Z',entries:[{rsid:'rs1801133',gene:'MTHFR',genotype}]});
export async function biologicalReportFixture(){
 const prior=process.env.PRECISION_DATA_KEY;process.env.PRECISION_DATA_KEY=randomBytes(32).toString('base64');const pg=new PGlite();
 await pg.exec(`CREATE TABLE users(id varchar PRIMARY KEY,dietary_preferences jsonb);INSERT INTO users(id)VALUES('report-a'),('report-b');CREATE TABLE microbiome_samples(id varchar PRIMARY KEY DEFAULT gen_random_uuid(),user_id varchar NOT NULL REFERENCES users(id),test_date timestamp NOT NULL,testing_company text,test_id text,raw_data_path text,structured_data jsonb,notes text,processing_status text NOT NULL DEFAULT 'completed',diversity_index real,uploaded_at timestamp NOT NULL DEFAULT now());CREATE TABLE bacterial_composition(id varchar PRIMARY KEY DEFAULT gen_random_uuid(),sample_id varchar NOT NULL REFERENCES microbiome_samples(id),bacterial_name text NOT NULL,taxonomy_level text NOT NULL,abundance real NOT NULL,genome_data jsonb);CREATE TABLE ml_analyses(id varchar PRIMARY KEY DEFAULT gen_random_uuid(),sample_id varchar NOT NULL REFERENCES microbiome_samples(id),analysis_type text NOT NULL,model_version text NOT NULL,results jsonb NOT NULL,confidence real,explainability jsonb,compared_cohorts text[],analyzed_at timestamp NOT NULL DEFAULT now());CREATE TABLE meals(id varchar PRIMARY KEY,user_id varchar NOT NULL REFERENCES users(id),meal_text text NOT NULL);INSERT INTO meals VALUES('journal-a','report-a','Independent synthetic journal');`);
 await pg.exec(reportDerivedTablesSql);await pg.exec(readFileSync(new URL('../../migrations/0002_precision_nutrition.sql',import.meta.url),'utf8'));const db=drizzle(pg),precision=new PrecisionStorage(db as any);
 const micro=async(data:unknown=null,owner='report-a',id?:string)=>{const[row]=await db.insert(microbiomeSamples).values({...(id?{id}:{}),userId:owner,testDate:new Date('2026-10-01T12:00:00Z'),testingCompany:'Synthetic source',processingStatus:'completed',structuredData:data}).returning();return row;};
 return{pg,db,precision,micro,close:async()=>{await pg.close();if(prior===undefined)delete process.env.PRECISION_DATA_KEY;else process.env.PRECISION_DATA_KEY=prior;}};
}
